import itertools, sys, json

def find_partition(L):
    L = sorted(L)
    # precompute possible sums mapping to c
    sums = {}
    for a, b in itertools.combinations(L, 2):
        s = a + b
        if s in L:
            sums.setdefault(s, []).append((a, b))
    # backtracking
    used = set()
    triples = []
    def backtrack():
        if len(triples) == 15:
            return True
        # choose smallest unused c that can be formed
        for c in L:
            if c in used:
                continue
            if c not in sums:
                continue
            for a, b in sums[c]:
                if a in used or b in used:
                    continue
                # pick this triple
                triples.append((a, b, c))
                used.update([a, b, c])
                if backtrack():
                    return True
                # backtrack
                triples.pop()
                used.difference_update([a, b, c])
        return False
    if backtrack():
        return triples
    return None

L = {71, 97, 54, 56, 44, 158, 45, 58, 82, 135, 113, 117, 86, 40, 12, 185, 63, 50, 111, 72, 90, 109, 61, 13, 92, 60, 91, 35, 114, 94, 105, 26, 15, 51, 102, 118, 76, 32, 108, 23, 22, 134, 83, 43, 64}
partition = find_partition(L)
