# Solution script to find a partition of the given list into triples (a,b,c) with a+b=c
# The script searches for a valid set of 15 disjoint triples and prints the result as a WITNESS line.
L = {71, 97, 54, 56, 44, 158, 45, 58, 82, 135, 113, 117, 86, 40, 12, 185, 63, 50, 111, 72, 90, 109, 61, 13, 92, 60, 91, 35, 114, 94, 105, 26, 15, 51, 102, 118, 76, 32, 108, 23, 22, 134, 83, 43, 64}

from itertools import combinations

# Precompute all possible triples where a+b=c and all three are distinct elements of L
def generate_triples(S):
    triples = []
    for a, b in combinations(S, 2):
        c = a + b
        if c in S and c != a and c != b:
            triples.append(tuple(sorted((a, b, c))))
    # Remove duplicates
    return list(set(triples))

triples = generate_triples(L)

# Sort triples to have deterministic search order
triples.sort()

# Recursive backtracking search
def search(remaining, start, chosen):
    if not remaining:
        return chosen
    for idx in range(start, len(triples)):
        a, b, c = triples[idx]
        if a in remaining and b in remaining and c in remaining:
            new_rem = remaining - {a, b, c}
            result = search(new_rem, idx + 1, chosen + [(a, b, c)])
            if result is not None:
                return result
    return None

solution = search(L, 0, [])
if solution is None:
    print('WITNESS: {"polarity": "negative", "evidence": {"path": "execution://witness"}, "basis": "search", "search_exhausted": true, "nodes_explored": null, "method": "backtrack"}')
else:
    # Prepare output dictionary
    out = {"triples": solution}
    print('WITNESS: ' + __import__('json').dumps(out))
